package com.example.airplanemode; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.widget.Toast; public class AirplaneModeReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent i){if(Intent.ACTION_AIRPLANE_MODE_CHANGED.equals(i.getAction())){boolean on=i.getBooleanExtra("state",false);Toast.makeText(c,on?"Airplane Mode turned ON":"Airplane Mode turned OFF",Toast.LENGTH_LONG).show();}}}
